const o=$json;
const now=new Date();
const next=o.next_follow_up_at?new Date(o.next_follow_up_at):null;
let decision='wait';
let reason='No follow-up condition met';
if(o.do_not_contact===true){decision='wait';reason='Do not contact';}
else if(o.human_required===true){decision='notify_human';reason=o.human_reason||'Human intervention required';}
else if(o.status==='proposal_sent' && !o.last_response_at && next && now>=next){decision='follow_up';reason='Proposal pending without response';}
else if(o.status==='engaged' && !o.next_action){decision='follow_up';reason='Interested opportunity has no next action';}
else if(o.status==='nurture' && next && now>=next){decision='follow_up';reason='Nurture reactivation is due';}
return [{json:{...o,decision,decision_reason:reason,evaluated_at:now.toISOString()}}];

const o=$json;
if(o.decision!=='follow_up') return [{json:o}];
const attempt=(o.follow_up_count||0)+1;
const max=3;
return [{json:{...o,follow_up_count:attempt,follow_up_allowed:attempt<=max,message_intent:o.status==='proposal_sent'?'proposal_follow_up':'contextual_follow_up'}}];

const o=$json;
let action=o.decision;
if(o.decision==='follow_up' && o.follow_up_allowed===false) action='nurture';
return [{json:{...o,final_action:action}}];
